@startuml

class Doctor {
  +practitionerNumber : int
  +fullName : string
  +address : string
  +phoneNumber : string
  +signature : string
}

class Patient {
  +healthNumber : string
  +firstName : string
  +lastName : string
  +dateOfBirth : date
  +address : string
  +phoneNumber : string
}

class Requisition {
  +validFrom : date
  +repetitionCount : int
  +repetitionInterval : Interval
}

enum Interval {
  WEEKLY
  MONTHLY
  EVERY_HALF_YEAR
  YEARLY
}

class Test {
  +duration : int
}

class TestResult {
  +isPositive : boolean
  +report : string
}

class Lab {
  +address : string
  +businessHoursStart : time
  +businessHoursEnd : time
  +registrationNumber : string
  +changeCancellationFee : float
}

class Appointment {
  +confirmationNumber : string
  +date : date
  +startTime : time
  +endTime : time
}

class AppointmentChangeFee {
  +fee : float
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : is subject of
Doctor "0..1" -- "*" Requisition : is subject of
Patient "1" -- "*" Appointment : makes
Requisition "1" -- "*" Appointment : for
Lab "1" -- "*" Appointment : hosts
Lab "1" -- "*" Test : offers
Test "1" -- "*" Appointment : scheduled for
Test "1" -- "*" TestResult : has
Test "1" -- "*" TestResult : has
Doctor "1" -- "*" TestResult : views
Patient "1" -- "*" TestResult : views

Requisition "1" *-- "1..*" Test : contains

@enduml

